mapper.select:
select `date`, `count`
from corgi_statistic_${table}
where `date` >= #{beginDate}
  and `date` <= #{endDate}

select sum(`count`) from corgi_statistic_${table}
where 1=1

    and `date`>= #{beginDate}


    and `date` <= #{endDate}

select *
from corgi_statistic_${table}
where `date` >= #{beginDate}
  and `date` <= #{endDate}

select `name`, `date`, `count`
from corgi_statistic_agg_${table}
where `date` >= #{beginDate}
  and `date` <= #{endDate}

select login_date loginDate,
       stay_date  stayDate,
       stay_count stayCount,
       `count`
from corgi_statistic_user_stay
where `login_date` >= #{beginDate}
  and `login_date` <= #{endDate}
  and stay_count <= ${stayCount}

mapper.update:
update corgi_statistic_trace
set `stay_status` = #{userTrace.stayStauts},
    `uptime`      = #{userTrace.uptime},
    next_type     = #{userTrace.nextType}
where id = #{userTrace.id}

mapper.select:
select `date`, `type`, `time`
from corgi_statistic_trace_total
where `date` >= #{beginDate}
  and `date` <= #{endDate}

select `character`
from corgi_statistic_character
where open_id = #{openId}

select count(distinct g.user_id) userCount, sum(price) totalSum
from corgi_user_goods g
where g.ctime > #{behavior.startTime}
  and g.ctime < #{behavior.endTime}
  and g.goods_type = #{behavior.type}

select count(distinct g.${userName}) userCount, count(1) totalSum from corgi_activity_${behavior.type} g where g.ctime > #{behavior.startTime} and g.ctime < #{behavior.endTime}
and g.type = 'real'
and g.status != 'fake'
